<?php get_header();?><section class="wrap linea-intro"><h1><?php echo esc_html(kl_mod('kl_heading','Архитектура для жизни'));?></h1><p><?php echo esc_html(kl_mod('kl_subtitle','Пространства, в которых хочется оставаться.'));?></p></section><div class="linea-cover"><?php kl_photo('linea-house','Современный дом среди сосен');?></div><section class="wrap selected"><div class="section-top"><h2>Избранные проекты</h2><nav class="filter-nav" aria-label="Проекты"><a class="active" href="<?php echo kl_url('projects');?>">Все</a><?php foreach(get_terms(['taxonomy'=>'kl_project_type','hide_empty'=>false]) as $t):?><a href="<?php echo esc_url(get_term_link($t));?>"><?php echo esc_html($t->name);?></a><?php endforeach;?></nav></div><div class="linea-projects"><?php foreach(kl_posts('kl_project',2) as $i=>$p):?><article><a href="<?php echo esc_url(get_permalink($p));?>"><img src="<?php echo kl_image($p->ID,$i?'linea-interior':'linea-house');?>" alt="<?php echo esc_attr($p->post_title);?>"><h3><?php echo esc_html($p->post_title);?></h3></a></article><?php endforeach;?></div></section><section class="wrap services"><h2>От первого эскиза<br>до последней детали</h2><?php foreach(kl_posts('kl_service',3) as $i=>$p):?><a class="service-row" href="<?php echo esc_url(get_permalink($p));?>"><span class="service-number"><?php echo esc_html('0'.($i+1));?></span><h3><?php echo esc_html($p->post_title);?></h3><p><?php echo esc_html($p->post_excerpt);?></p></a><?php endforeach;?><a class="text-link" href="<?php echo kl_url('contacts');?>">Обсудить проект <?php kl_arrow();?></a></section><?php get_footer();?>
